parameters.jsCode:
const raw = String($json.output ?? "").trim();

const cleaned = raw
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

try {
  const decision = JSON.parse(cleaned);
  return [{ json: { ...decision, rawOutput: raw } }];
} catch (error) {
  return [{
    json: {
      action: "reply",
      reply: raw || "Desculpe, não consegui interpretar sua solicitação. Poderia repetir?",
      appointmentType: null,
      procedureId: null,
      procedureName: null,
      doctorId: null,
      doctorName: null,
      date: null,
      time: null,
      patientName: null,
      patientEmail: null,
      patientSex: null,
      rawOutput: raw,
      parseError: true
    }
  }];
}

const decision = $('Interpretar decisão da IA').item.json;
const [year, month, day] = String($json.date ?? decision.date).split("-");
const formattedDate = `${day}/${month}/${year}`;
const isProcedure = decision.appointmentType === "procedure";
const selectedName = isProcedure
  ? decision.procedureName
  : (decision.doctorName ?? $json.doctor?.name);

const availableTimes = ($json.times ?? [])
  .filter((slot) => slot.available)
  .map((slot) => slot.label);

let reply;
if (availableTimes.length === 0) {
  reply = `Não encontrei horários disponíveis para ${selectedName ?? "a opção selecionada"} em ${formattedDate}. Deseja consultar outra data?`;
} else {
  const professional = decision.doctorName ? ` com ${decision.doctorName}` : "";
  reply =
    `Para ${formattedDate}, há estes horários disponíveis para ${selectedName ?? "a opção selecionada"}${isProcedure ? professional : ""}:\n\n` +
    availableTimes.join(", ") +
    "\n\nQual horário você gostaria de escolher?";
}

return [{ json: { reply } }];

